import torch
import torch.nn as nn
from torch.optim import AdamW


class Accuracy:
    """Accuracy metric."""

    __name__ = "accuracy"

    def __init__(self):
        self.correct = 0
        self.total = 0

    def __call__(self, output, target):
        pred = output.argmax(dim=1)
        self.correct += (pred == target).sum().item()
        self.total += target.size(0)

    def compute(self):
        return self.correct / self.total if self.total > 0 else 0.0

    def reset(self):
        self.correct = 0
        self.total = 0


class VisionLearner:
    """Vision learner wrapper."""

    def __init__(self, arch, n_out, metrics):
        self.arch = arch
        self.n_out = n_out
        self.metrics = metrics
        self.framework = "fatai"


def accuracy(output, target):
    """Compute accuracy."""
    pred = output.argmax(dim=1)
    return (pred == target).float().mean()


def vision_learner(arch, n_out, metrics):
    """Create a vision learner."""
    return VisionLearner(arch=arch, n_out=n_out, metrics=metrics)


